// Validate recognition payload and prepare thank you data
const recognition = $input.first().json;

// Skip system-generated recognitions (avoid infinite loops)
if (recognition.sender_id === 'system') {
  return { skip: true, reason: 'System-generated recognition' };
}

// Skip if recipient has opted out of auto-thanks
if (recognition.recipient_preferences?.auto_thanks === false) {
  return { skip: true, reason: 'Recipient opted out' };
}

// Generate personalized thank you suggestions based on recognition type
const thankYouTemplates = {
  kudos: [
    `Thank you so much for the recognition, {sender_name}! 🙏 It really made my day!`,
    `I really appreciate you taking the time to recognize this, {sender_name}! 💙`,
    `Wow, thank you {sender_name}! This means a lot coming from you! 🌟`
  ],
  achievement: [
    `Thank you for celebrating this milestone with me, {sender_name}! 🏆`,
    `I'm grateful for your support, {sender_name}! Couldn't have done it without the team! 🎯`,
    `Thanks {sender_name}! Excited to keep pushing forward! 🚀`
  ],
  teamwork: [
    `Thank you {sender_name}! Teamwork makes the dream work! 🤝`,
    `Appreciate the shoutout, {sender_name}! Love working with this amazing team! 💪`,
    `Thanks {sender_name}! We really do have the best team! ⭐`
  ],
  default: [
    `Thank you so much, {sender_name}! 🙏`,
    `Really appreciate the recognition, {sender_name}! 💙`,
    `Thanks {sender_name}! This made my day! 🌟`
  ]
};

const recognitionType = recognition.tags?.includes('teamwork') ? 'teamwork' :
                        recognition.tags?.includes('achievement') ? 'achievement' :
                        recognition.tags?.includes('kudos') ? 'kudos' : 'default';

const templates = thankYouTemplates[recognitionType];
const randomTemplate = templates[Math.floor(Math.random() * templates.length)];
const thankYouMessage = randomTemplate.replace('{sender_name}', recognition.sender_name);

return {
  skip: false,
  recognition_id: recognition.id,
  recipient_id: recognition.recipient_id,
  recipient_name: recognition.recipient_name,
  recipient_email: recognition.recipient_email,
  sender_id: recognition.sender_id,
  sender_name: recognition.sender_name,
  sender_email: recognition.sender_email,
  original_message: recognition.message,
  points_received: recognition.points,
  thank_you_suggestion: thankYouMessage,
  recognition_type: recognitionType,
  created_at: new Date().toISOString()
};

